from jsonb_to_recordset($notes$[{"choice_id":"6","judgment_id":"g3s2-mul-01","misconception_key":"multiplication.place-value.place-weight-lost","misconception_title":"곱해지는 수의 자릿값을 없앰","set_key":"grade3-semester2","signal_ids":["multiplication.place-value-loss"],"teacher_note":"20의 십의 자리 값을 없애고 2만 곱해 작은 수를 만들었습니다.","version":"2.1.0"},{"choice_id":"23","judgment_id":"g3s2-mul-01","misconception_key":"multiplication.place-value.operation-substituted","misconception_title":"곱셈을 덧셈으로 바꿈","set_key":"grade3-semester2","signal_ids":["multiplication.place-value-loss"],"teacher_note":"20이 세 묶음이라는 관계를 사용하지 않고 두 수를 더했습니다.","version":"2.1.0"},{"choice_id":"90","judgment_id":"g3s2-mul-03","misconception_key":"multiplication.place-value.place-weight-lost","misconception_title":"곱해지는 수의 자릿값을 없앰","set_key":"grade3-semester2","signal_ids":["multiplication.place-value-loss"],"teacher_note":"300을 30으로 줄여 백의 자리 한 칸을 빠뜨린 채 곱했습니다.","version":"2.1.0"},{"choice_id":"327","judgment_id":"g3s2-mul-03","misconception_key":"multiplication.place-value.operation-substituted","misconception_title":"곱셈을 덧셈으로 바꿈","set_key":"grade3-semester2","signal_ids":["multiplication.place-value-loss"],"teacher_note":"상자 한 개의 전체 수 324와 상자 수 3을 곱하지 않고 더했습니다.","version":"2.1.0"},{"choice_id":"612","judgment_id":"g3s2-mul-02","misconception_key":"multiplication.combine.partial-products-combined-without-place-value","misconception_title":"부분곱을 자릿값에 맞게 합치지 못함","set_key":"grade3-semester2","signal_ids":["multiplication.partial-product"],"teacher_note":"60과 12를 같은 자리끼리 더하지 않고 보이는 숫자 순서대로 붙였습니다.","version":"2.1.0"},{"choice_id":"27","judgment_id":"g3s2-mul-02","misconception_key":"multiplication.combine.partial-product-omitted","misconception_title":"필요한 부분곱을 결과에 반영하지 못함","set_key":"grade3-semester2","signal_ids":["multiplication.partial-product"],"teacher_note":"두 부분곱의 값을 합치지 않고 원래 수의 숫자를 다시 더했습니다.","version":"2.1.0"},{"choice_id":"721","judgment_id":"g3s2-mul-04","misconception_key":"multiplication.combine.partial-products-combined-without-place-value","misconception_title":"부분곱을 자릿값에 맞게 합치지 못함","set_key":"grade3-semester2","signal_ids":["multiplication.partial-product"],"teacher_note":"십의 자리 부분곱 120에서 20을 빠뜨려 바른 답보다 20 작게 합쳤습니다.","version":"2.1.0"},{"choice_id":"621","judgment_id":"g3s2-mul-04","misconception_key":"multiplication.combine.partial-product-omitted","misconception_title":"필요한 부분곱을 결과에 반영하지 못함","set_key":"grade3-semester2","signal_ids":["multiplication.partial-product"],"teacher_note":"40×3의 부분곱을 빼고 백과 일의 부분곱만 더했습니다.","version":"2.1.0"},{"choice_id":"2346","judgment_id":"g3s2-mul-05","misconception_key":"multiplication.two-digit.partial-products-combined-incorrectly","misconception_title":"부분곱을 합칠 때 자릿값을 보존하지 못함","set_key":"grade3-semester2","signal_ids":["multiplication.two-digit-factor"],"teacher_note":"십의 자리 부분곱 230에서 0을 버리고 23과 일의 자리 부분곱 46을 이어 붙였습니다.","version":"2.1.0"},{"choice_id":"253","judgment_id":"g3s2-mul-05","misconception_key":"multiplication.two-digit.multiplicative-structure-replaced-by-addition","misconception_title":"두 자리 수의 곱을 부분곱 대신 덧셈으로 바꿈","set_key":"grade3-semester2","signal_ids":["multiplication.two-digit-factor"],"teacher_note":"12를 10과 2로 나누지 않고 23에 두 자리 숫자를 한 번 더했습니다.","version":"2.1.0"},{"choice_id":"284","judgment_id":"g3s2-mul-06","misconception_key":"multiplication.two-digit.partial-products-combined-incorrectly","misconception_title":"부분곱을 합칠 때 자릿값을 보존하지 못함","set_key":"grade3-semester2","signal_ids":["multiplication.two-digit-factor"],"teacher_note":"14×20과 14×1의 두 부분곱을 더할 때 일의 부분을 4만 더했습니다.","version":"2.1.0"},{"choice_id":"35","judgment_id":"g3s2-mul-06","misconception_key":"multiplication.two-digit.multiplicative-structure-replaced-by-addition","misconception_title":"두 자리 수의 곱을 부분곱 대신 덧셈으로 바꿈","set_key":"grade3-semester2","signal_ids":["multiplication.two-digit-factor"],"teacher_note":"14가 21묶음이라는 뜻을 사용하지 않고 두 수를 더했습니다.","version":"2.1.0"},{"choice_id":"30","judgment_id":"g3s2-mul-07","misconception_key":"multiplication.estimate.one-place-too-small","misconception_title":"곱의 자릿수를 한 자리 작게 어림함","set_key":"grade3-semester2","signal_ids":["multiplication.estimate"],"teacher_note":"48을 50으로 보면서도 6묶음의 크기를 십의 자리에서 멈췄습니다.","version":"2.1.0"},{"choice_id":"3000","judgment_id":"g3s2-mul-07","misconception_key":"multiplication.estimate.one-place-too-large","misconception_title":"곱의 자릿수를 한 자리 크게 어림함","set_key":"grade3-semester2","signal_ids":["multiplication.estimate"],"teacher_note":"두 자리 수와 한 자리 수의 곱을 천의 자리까지 과대하게 보았습니다.","version":"2.1.0"},{"choice_id":"about-60","judgment_id":"g3s2-mul-08","misconception_key":"multiplication.estimate.one-place-too-small","misconception_title":"곱의 자릿수를 한 자리 작게 어림함","set_key":"grade3-semester2","signal_ids":["multiplication.estimate"],"teacher_note":"약 30개가 약 20줄 있다는 반복을 반영하지 않아 백의 자리를 놓쳤습니다.","version":"2.1.0"},{"choice_id":"about-6000","judgment_id":"g3s2-mul-08","misconception_key":"multiplication.estimate.one-place-too-large","misconception_title":"곱의 자릿수를 한 자리 크게 어림함","set_key":"grade3-semester2","signal_ids":["multiplication.estimate"],"teacher_note":"30과 20의 곱에 필요하지 않은 0을 하나 더 붙여 크기를 부풀렸습니다.","version":"2.1.0"},{"choice_id":"6-groups","judgment_id":"g3s2-div-05","misconception_key":"division.meaning.divisor-as-answer","misconception_title":"나누는 수를 그대로 답으로 삼음","set_key":"grade3-semester2","signal_ids":["division.meaning"],"teacher_note":"한 묶음에 6개라는 정보를 묶음의 개수로 그대로 읽었습니다.","version":"2.1.0"},{"choice_id":"18-groups","judgment_id":"g3s2-div-05","misconception_key":"division.meaning.division-replaced","misconception_title":"나눗셈을 뺄셈이나 남은 수로 바꿈","set_key":"grade3-semester2","signal_ids":["division.meaning"],"teacher_note":"24에서 한 묶음 6개만 덜고 남은 수를 묶음 수로 보았습니다.","version":"2.1.0"},{"choice_id":"35-div-5-wrong","judgment_id":"g3s2-div-06","misconception_key":"division.meaning.divisor-as-answer","misconception_title":"나누는 수를 그대로 답으로 삼음","set_key":"grade3-semester2","signal_ids":["division.meaning"],"teacher_note":"35를 접시 5개로 나눈 몫 대신 접시 수 5를 답으로 삼았습니다.","version":"2.1.0"},{"choice_id":"35-minus-5","judgment_id":"g3s2-div-06","misconception_key":"division.meaning.division-replaced","misconception_title":"나눗셈을 뺄셈이나 남은 수로 바꿈","set_key":"grade3-semester2","signal_ids":["division.meaning"],"teacher_note":"전체를 똑같이 나누지 않고 접시 한 개 분량처럼 5만 뺐습니다.","version":"2.1.0"},{"choice_id":"8","judgment_id":"g3s2-div-01","misconception_key":"division.remainder.component-relation-misapplied","misconception_title":"전체·나눈 양·남은 양의 관계식을 잘못 구성함","set_key":"grade3-semester2","signal_ids":["division.leftover"],"teacher_note":"나누어 준 40개뿐 아니라 사람 수 4도 사탕 수에서 한 번 더 뺐습니다.","version":"2.1.0"},{"choice_id":"2","judgment_id":"g3s2-div-01","misconception_key":"division.remainder.partial-value-used-as-result","misconception_title":"계산 결과의 일부나 남은 부분만 답으로 사용함","set_key":"grade3-semester2","signal_ids":["division.leftover"],"teacher_note":"52에서 40을 뺀 십의 자리 1을 버리고 일의 자리만 남겼습니다.","version":"2.1.0"},{"choice_id":"40-total","judgment_id":"g3s2-div-03","misconception_key":"division.remainder.component-relation-misapplied","misconception_title":"전체·나눈 양·남은 양의 관계식을 잘못 구성함","set_key":"grade3-semester2","signal_ids":["division.leftover"],"teacher_note":"상자에 먼저 담은 공만 세고 아직 남아 있는 공을 전체에 합치지 않았습니다.","version":"2.1.0"},{"choice_id":"28-left","judgment_id":"g3s2-div-03","misconception_key":"division.remainder.partial-value-used-as-result","misconception_title":"계산 결과의 일부나 남은 부분만 답으로 사용함","set_key":"grade3-semester2","signal_ids":["division.leftover"],"teacher_note":"처음 전체를 묻는데도 아직 남은 28개만 전체라고 판단했습니다.","version":"2.1.0"},{"choice_id":"4","judgment_id":"g3s2-div-02","misconception_key":"division.equal-sharing.group-count-as-quotient","misconception_title":"묶음 수를 몫으로 그대로 사용함","set_key":"grade3-semester2","signal_ids":["division.equal-share"],"teacher_note":"4명에게 나눈다는 조건의 사람 수를 한 사람 몫으로 그대로 골랐습니다.","version":"2.1.0"},{"choice_id":"8","judgment_id":"g3s2-div-02","misconception_key":"division.equal-sharing.division-replaced-by-add-subtract","misconception_title":"나눗셈을 덧셈이나 뺄셈으로 바꿈","set_key":"grade3-semester2","signal_ids":["division.equal-share"],"teacher_note":"12개를 네 몫으로 나누지 않고 전체에서 사람 수만 뺐습니다.","version":"2.1.0"},{"choice_id":"3-boxes","judgment_id":"g3s2-div-04","misconception_key":"division.equal-sharing.group-count-as-quotient","misconception_title":"묶음 수를 몫으로 그대로 사용함","set_key":"grade3-semester2","signal_ids":["division.equal-share"],"teacher_note":"상자 3개에 나눈다는 조건의 상자 수를 한 상자 몫으로 그대로 골랐습니다.","version":"2.1.0"},{"choice_id":"21","judgment_id":"g3s2-div-04","misconception_key":"division.equal-sharing.division-replaced-by-add-subtract","misconception_title":"나눗셈을 덧셈이나 뺄셈으로 바꿈","set_key":"grade3-semester2","signal_ids":["division.equal-share"],"teacher_note":"전체를 세 상자로 나누지 않고 전체와 상자 수를 더했습니다.","version":"2.1.0"},{"choice_id":"4x7-minus1","judgment_id":"g3s2-div-07","misconception_key":"division.remainder-check.remainder-operation-wrong","misconception_title":"나머지를 더하지 않고 빼거나 위치를 바꿈","set_key":"grade3-semester2","signal_ids":["division.remainder-check"],"teacher_note":"전체를 복원할 때 남은 1을 더하지 않고 곱에서 뺐습니다.","version":"2.1.0"},{"choice_id":"4plus7plus1","judgment_id":"g3s2-div-07","misconception_key":"division.remainder-check.confirmation-structure-rebuilt","misconception_title":"나누는 수×몫+나머지 구조를 다른 식으로 바꿈","set_key":"grade3-semester2","signal_ids":["division.remainder-check"],"teacher_note":"7묶음에 4개씩이라는 관계를 곱셈으로 묶지 않고 모두 더했습니다.","version":"2.1.0"},{"choice_id":"6x5-plus7","judgment_id":"g3s2-div-08","misconception_key":"division.remainder-check.remainder-operation-wrong","misconception_title":"나머지를 더하지 않고 빼거나 위치를 바꿈","set_key":"grade3-semester2","signal_ids":["division.remainder-check"],"teacher_note":"몫 7과 나머지 5의 자리를 바꾸어 곱셈에 나머지를 사용했습니다.","version":"2.1.0"},{"choice_id":"7x5-plus6","judgment_id":"g3s2-div-08","misconception_key":"division.remainder-check.confirmation-structure-rebuilt","misconception_title":"나누는 수×몫+나머지 구조를 다른 식으로 바꿈","set_key":"grade3-semester2","signal_ids":["division.remainder-check"],"teacher_note":"나누는 수·몫·나머지의 역할을 모두 바꾸어 임의의 곱과 합을 만들었습니다.","version":"2.1.0"},{"choice_id":"about-2","judgment_id":"g3s2-div-09","misconception_key":"division.estimate.quotient-place-too-small","misconception_title":"몫의 자릿수를 한 자리 작게 어림함","set_key":"grade3-semester2","signal_ids":["division.estimate"],"teacher_note":"80을 4로 나누는 크기에서 십의 자리를 없애 몫을 너무 작게 잡았습니다.","version":"2.1.0"},{"choice_id":"about-200","judgment_id":"g3s2-div-09","misconception_key":"division.estimate.quotient-scale-too-large","misconception_title":"몫의 크기를 실제보다 크게 어림함","set_key":"grade3-semester2","signal_ids":["division.estimate"],"teacher_note":"두 자리 수를 4로 나누는데도 몫을 백의 자리로 크게 보았습니다.","version":"2.1.0"},{"choice_id":"about-2-each","judgment_id":"g3s2-div-10","misconception_key":"division.estimate.quotient-place-too-small","misconception_title":"몫의 자릿수를 한 자리 작게 어림함","set_key":"grade3-semester2","signal_ids":["division.estimate"],"teacher_note":"160개를 8명에게 나누는 몫에서 십의 자리 크기를 반영하지 않았습니다.","version":"2.1.0"},{"choice_id":"about-80-each","judgment_id":"g3s2-div-10","misconception_key":"division.estimate.quotient-scale-too-large","misconception_title":"몫의 크기를 실제보다 크게 어림함","set_key":"grade3-semester2","signal_ids":["division.estimate"],"teacher_note":"158의 절반에 가까운 수를 골라 8명에게 나눈다는 조건을 약하게 적용했습니다.","version":"2.1.0"},{"choice_id":"diameter","judgment_id":"g3s2-circle-01","misconception_key":"circle.parts.radius-diameter-confused","misconception_title":"반지름을 지름으로 부름","set_key":"grade3-semester2","signal_ids":["circle.center-radius"],"teacher_note":"중심에서 원 위까지 한쪽만 이은 선분을 원을 가로지르는 지름으로 보았습니다.","version":"2.1.0"},{"choice_id":"circumference","judgment_id":"g3s2-circle-01","misconception_key":"circle.parts.line-and-point-confused","misconception_title":"선분을 둘레나 중심점으로 부름","set_key":"grade3-semester2","signal_ids":["circle.center-radius"],"teacher_note":"원의 안쪽 선분과 원의 가장자리를 이루는 굽은 선을 구분하지 못했습니다.","version":"2.1.0"},{"choice_id":"diameter-oa","judgment_id":"g3s2-circle-03","misconception_key":"circle.parts.radius-diameter-confused","misconception_title":"반지름을 지름으로 부름","set_key":"grade3-semester2","signal_ids":["circle.center-radius"],"teacher_note":"O에서 A까지의 한쪽 선분이 반대쪽 원 위까지 이어진다고 보았습니다.","version":"2.1.0"},{"choice_id":"center-oa","judgment_id":"g3s2-circle-03","misconception_key":"circle.parts.line-and-point-confused","misconception_title":"선분을 둘레나 중심점으로 부름","set_key":"grade3-semester2","signal_ids":["circle.center-radius"],"teacher_note":"가운데 점 O의 이름을 O와 A를 이은 선분의 이름으로 옮겼습니다.","version":"2.1.0"},{"choice_id":"6cm","judgment_id":"g3s2-circle-05","misconception_key":"circle.equal-radii.diameter-rule-applied","misconception_title":"반지름에 지름의 두 배 관계를 적용함","set_key":"grade3-semester2","signal_ids":["circle.equal-radii"],"teacher_note":"다른 반지름을 구하면서 반지름 두 개가 지름이라는 관계를 잘못 적용했습니다.","version":"2.1.0"},{"choice_id":"1cm","judgment_id":"g3s2-circle-05","misconception_key":"circle.equal-radii.direction-changes-length","misconception_title":"방향에 따라 반지름 길이가 달라진다고 봄","set_key":"grade3-semester2","signal_ids":["circle.equal-radii"],"teacher_note":"같은 원에서도 방향이 달라지면 중심에서 가장자리까지의 길이가 달라진다고 보았습니다.","version":"2.1.0"},{"choice_id":"all-different","judgment_id":"g3s2-circle-06","misconception_key":"circle.equal-radii.direction-changes-length","misconception_title":"방향에 따라 반지름 길이가 달라진다고 봄","set_key":"grade3-semester2","signal_ids":["circle.equal-radii"],"teacher_note":"중심은 같아도 가장자리의 위치마다 거리가 모두 달라진다고 판단했습니다.","version":"2.1.0"},{"choice_id":"one-double","judgment_id":"g3s2-circle-06","misconception_key":"circle.equal-radii.diameter-rule-applied","misconception_title":"반지름에 지름의 두 배 관계를 적용함","set_key":"grade3-semester2","signal_ids":["circle.equal-radii"],"teacher_note":"한 방향의 선분만 반대편까지 이어진 지름처럼 두 배라고 보았습니다.","version":"2.1.0"},{"choice_id":"4cm","judgment_id":"g3s2-circle-02","misconception_key":"circle.diameter.diameter-equals-radius","misconception_title":"지름을 반지름 한 개 길이로 봄","set_key":"grade3-semester2","signal_ids":["circle.radius-diameter"],"teacher_note":"지름이 중심의 양쪽 반지름으로 이루어진다는 점을 반영하지 않았습니다.","version":"2.1.0"},{"choice_id":"16cm","judgment_id":"g3